namespace ProductCatalog.Api.Domain;

/// <summary>
/// A product that can be sold and whose available stock is tracked.
/// This is the only persisted entity; it maps to the <c>Products</c> table.
/// </summary>
public class Product
{
    /// <summary>
    /// Unique six-digit identifier (100000-999999).
    /// Never assigned by application code: it is generated by a database sequence so that
    /// several API instances can insert concurrently without producing duplicates.
    /// </summary>
    public int Id { get; set; }

    /// <summary>Display name of the product (required, max 200 characters).</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Optional free-text description (max 1000 characters).</summary>
    public string? Description { get; set; }

    /// <summary>Unit price. Must be greater than zero (also enforced by a CHECK constraint).</summary>
    public decimal Price { get; set; }

    /// <summary>Units currently available. Never negative (also enforced by a CHECK constraint).</summary>
    public int Stock { get; set; }

    /// <summary>
    /// Optimistic-concurrency token maintained by SQL Server (<c>rowversion</c>).
    /// It changes on every update, which lets EF Core detect conflicting concurrent edits.
    /// </summary>
    public byte[] RowVersion { get; set; } = [];
}
